package com.sobrenaturaldirector.decision.random;
import java.nio.charset.Charset; import java.security.MessageDigest; import java.security.NoSuchAlgorithmException; import java.util.Random;
/** Stable SHA-256 derived streams. No platform hashCode participates. */
public final class DeterministicRng { private final Random random; private final long seed; private long draws; private DeterministicRng(long seed){this.seed=seed;random=new Random(seed);} public static DeterministicRng stream(long directorSeed,String stream,String identity){return new DeterministicRng(derive(directorSeed,stream,identity));} private static long derive(long seed,String stream,String identity){try{byte[] h=MessageDigest.getInstance("SHA-256").digest((Long.toString(seed)+":"+stream+":"+identity).getBytes(Charset.forName("UTF-8")));long v=0;for(int i=0;i<8;i++)v=(v<<8)|(h[i]&255L);return v;}catch(NoSuchAlgorithmException e){throw new IllegalStateException("SHA-256 unavailable",e);}} public int nextInt(int bound){if(bound<=0)throw new IllegalArgumentException("bound");draws++;return random.nextInt(bound);} public long getSeed(){return seed;} public long getDraws(){return draws;} }
